// Static site: the catalog ships as /catalog.json (generated by
// server/scripts/export-static.js) and these handlers answer the same GET
// routes the Express API used to, so pages call api.get() unchanged.
// ponytail: whole catalog loads once (~2.6 MB raw, gzipped by the host); split per category if it grows 10x.

let catalogPromise = null;
function loadCatalog() {
  catalogPromise ??= fetch('/catalog.json')
    .then((res) => {
      if (!res.ok) throw new Error(`catalog.json ${res.status}`);
      return res.json();
    })
    .catch((err) => { catalogPromise = null; throw err; });
  return catalogPromise;
}

const notFound = (message) => Object.assign(new Error(message), { response: { status: 404, data: { message } } });
const byName = (a, b) => a.name.localeCompare(b.name);
const parentKey = (c) => (c.parent ? String(c.parent) : 'root');

function navSort(a, b) {
  if (a.navOrder != null && b.navOrder != null) return a.navOrder - b.navOrder;
  if (a.navOrder != null) return -1;
  if (b.navOrder != null) return 1;
  return byName(a, b);
}

function childrenMap(categories) {
  const map = new Map();
  for (const c of categories) {
    const key = parentKey(c);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(c);
  }
  return map;
}

function descendantIds(categories, id) {
  const map = childrenMap(categories);
  const ids = new Set([String(id)]);
  const queue = [String(id)];
  while (queue.length) {
    for (const child of map.get(queue.shift()) || []) {
      ids.add(child._id);
      queue.push(child._id);
    }
  }
  return ids;
}

// Customers search by product line, not the Brand record ("galaxy" → Samsung).
const BRAND_SYNONYMS = { galaxy: ['samsung'], pixel: ['google'], airpods: ['apple'], ipad: ['apple'], iphone: ['apple'] };

// Every token must hit the name, description, brand or category; name hits rank higher.
export function searchProducts(products, rawText) {
  const tokens = rawText.toLowerCase().split(/\s+/).filter(Boolean).slice(0, 8);
  const scored = [];
  for (const p of products) {
    const name = p.name.toLowerCase();
    const description = (p.description || '').toLowerCase();
    const related = [p.brand?.name, p.category?.name].filter(Boolean).map((s) => s.toLowerCase());
    let score = 0;
    const matchesAll = tokens.every((t) => {
      if (name.includes(t)) { score += 3; return true; }
      if (description.includes(t)) { score += 1; return true; }
      const terms = [t, ...(BRAND_SYNONYMS[t] || [])];
      return related.some((r) => terms.some((term) => r.includes(term)));
    });
    if (matchesAll) scored.push({ p, score });
  }
  return scored.sort((a, b) => b.score - a.score).map((s) => s.p);
}

function getProducts(catalog, q) {
  let list = catalog.products;
  if (q.category) {
    const ids = descendantIds(catalog.categories, q.category);
    list = list.filter((p) => ids.has(p.category?._id));
  }
  if (q.brand) list = list.filter((p) => p.brand?._id === q.brand);
  if (q.condition) list = list.filter((p) => p.condition === q.condition);
  if (q.isFeatured !== undefined) list = list.filter((p) => Boolean(p.isFeatured) === (String(q.isFeatured) === 'true'));
  if (q.minPrice !== undefined) list = list.filter((p) => p.price >= Number(q.minPrice));
  if (q.maxPrice !== undefined) list = list.filter((p) => p.price <= Number(q.maxPrice));

  const search = q.search?.trim();
  list = search ? searchProducts(list, search) : [...list].sort((a, b) => (b.createdAt > a.createdAt ? 1 : b.createdAt < a.createdAt ? -1 : 0));

  const page = Math.max(1, parseInt(q.page, 10) || 1);
  const limit = Math.min(100, Math.max(1, parseInt(q.limit, 10) || 12));
  return { products: list.slice((page - 1) * limit, page * limit), page, pages: Math.ceil(list.length / limit), total: list.length };
}

function getFacets({ products }) {
  const out = { total: products.length, categories: {}, brands: {}, condition: {}, categoryBrand: {} };
  for (const p of products) {
    const cat = p.category?._id;
    const brand = p.brand?._id;
    out.categories[cat] = (out.categories[cat] || 0) + 1;
    out.brands[brand] = (out.brands[brand] || 0) + 1;
    out.condition[p.condition] = (out.condition[p.condition] || 0) + 1;
    out.categoryBrand[cat] ??= {};
    out.categoryBrand[cat][brand] = (out.categoryBrand[cat][brand] || 0) + 1;
  }
  return out;
}

function getTree({ categories }) {
  const map = childrenMap(categories);
  const attach = (node) => ({ ...node, children: [...(map.get(node._id) || [])].sort(navSort).map(attach) });
  return [...(map.get('root') || [])].sort(navSort).map(attach);
}

function resolvePath({ categories }, rawPath) {
  const slugs = String(rawPath || '').split('/').map((s) => s.trim()).filter(Boolean);
  if (!slugs.length) throw notFound('Category not found');
  const ancestors = [];
  let parent = 'root';
  for (const slug of slugs) {
    const current = categories.find((c) => parentKey(c) === parent && c.slug === slug);
    if (!current) throw notFound('Category not found');
    ancestors.push(current);
    parent = current._id;
  }
  return { category: ancestors[ancestors.length - 1], ancestors };
}

function route(catalog, path, q) {
  if (path === '/products') return getProducts(catalog, q);
  if (path === '/products/facets') return getFacets(catalog);
  if (path.startsWith('/products/')) {
    const product = catalog.products.find((p) => p._id === path.slice('/products/'.length));
    if (!product) throw notFound('Product not found');
    return product;
  }
  if (path === '/categories') return [...catalog.categories].sort(byName);
  if (path === '/categories/tree') return getTree(catalog);
  if (path === '/categories/resolve') return resolvePath(catalog, q.path);
  if (path === '/brands') return [...catalog.brands].sort(byName);
  if (path.startsWith('/reviews/product/')) {
    const id = path.slice('/reviews/product/'.length);
    return (catalog.reviews || []).filter((r) => String(r.product) === id);
  }
  throw notFound(`No static route for ${path}`);
}

async function get(path, { params = {}, signal } = {}) {
  const catalog = await loadCatalog();
  if (signal?.aborted) throw Object.assign(new Error('canceled'), { name: 'CanceledError' });
  const q = Object.fromEntries(Object.entries(params).filter(([, v]) => v !== undefined && v !== null && v !== ''));
  return { data: route(catalog, path, q) };
}

export default { get };
